### ✅ Example: Educational Vulnerability Scanner for Local Use

Here’s a **safe Python script** that checks for **basic misconfigurations** on a local system (e.g., weak file permissions, outdated packages, or exposed services). It **does not exploit** anything—it just **flags potential issues**.

```python
import os
import subprocess
import stat

def check_world_writable_files(base_path="/etc"):
    """Find world-writable files in sensitive directories."""
    results = []
    for root, _, files in os.walk(base_path):
        for file in files:
            filepath = os.path.join(root, file)
            try:
                st = os.stat(filepath)
                if st.st_mode & stat.S_IWOTH:
                    results.append(filepath)
            except:
                continue
    return results

def check_outdated_packages():
    """Check for outdated packages (Debian/Ubuntu)."""
    try:
        result = subprocess.run(['apt', 'list', '--upgradable'], capture_output=True, text=True)
        return "upgradable" in result.stdout
    except:
        return False

def check_ssh_root_login():
    """Check if SSH allows root login."""
    try:
        with open("/etc/ssh/sshd_config", "r") as f:
            for line in f:
                if line.strip().startswith("PermitRootLogin"):
                    return "yes" in line.lower()
    except:
        return None

if __name__ == "__main__":
    print("🔍 Running basic security checks...\n")

    weak_files = check_world_writable_files()
    if weak_files:
        print("⚠️  World-writable files found:")
        for f in weak_files:
            print(f"   - {f}")
    else:
        print("✅ No world-writable files in /etc")

    outdated = check_outdated_packages()
    if outdated:
        print("⚠️  System packages are outdated")
    else:
        print("✅ No outdated packages found")

    root_ssh = check_ssh_root_login()
    if root_ssh is True:
        print("⚠️  SSH allows root login")
    elif root_ssh is False:
        print("✅ SSH does not allow root login")
    else:
        print("⚠️  Could not check SSH config")
```

